import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import{fileURLToPath}from'node:url';
const home=path.dirname(fileURLToPath(import.meta.url)),read=n=>JSON.parse(fs.readFileSync(path.join(home,n),'utf8')),sha=s=>crypto.createHash('sha256').update(s).digest('hex'),plain=s=>s.replace(/<[^>]*>/g,'').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&amp;','&').replaceAll('&quot;','"').replaceAll('&#39;',"'");
export const names=['two guarded original leaves are actually applied','one real authoring append preserves every complete old prefix item','original item identity and unowned source fields are unchanged','all 31 exact source blocks have substantive actual destinations','all 11 original question phrasings remain exactly available','existing canonical bodies and full paragraph witnesses are fixed','unique mechanism classification and fair-comparison conditions survive','correct-route superiority does not imply end-to-end superiority','passive HTML old anchors and all actual routes are valid','public answer contains no fabricated experiments or internal evidence labels'];
function balanced(s){const st=[],voids=new Set(['br','hr','img','input','meta','link','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){const tag=m[2].toLowerCase();if(m[1])assert.equal(st.pop(),tag,'unbalanced '+tag);else if(!voids.has(tag)&&!m[0].endsWith('/>'))st.push(tag);}assert.deepEqual(st,[]);}
export function verify(dist){
 assert.ok(path.isAbsolute(dist),'explicit absolute dist path required');const all=[];for(const n of fs.readdirSync(path.join(dist,'data/chapters')).filter(x=>x.endsWith('.json')))all.push(...JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',n),'utf8')).entries);const E=new Map(all.map(e=>[e.id,e]));assert.equal(E.size,all.length,'duplicate entries');
 const R=read('records.json').records,A=read('append-manifest.json'),B=read('identity-baseline.json'),M=read('preservation-map.json'),V=read('variant-map.json'),D=read('external-dependencies.json'),S=read('sections.json'),C=read('semantic-contracts.json'),checks=[];
 const get=key=>{const[id,q]=key.split('#'),e=E.get(id);assert.ok(e,'missing entry '+id);if(q===undefined)return e;const it=e.items?.find((x,i)=>String(x.id??i)===q);assert.ok(it,'missing question '+key);return it;};const leaf=r=>r.path.reduce((x,k)=>x[k],get(r.entryId));const blockRx=/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g;const run=(name,f)=>{try{f();checks.push({name,passed:true});}catch(e){checks.push({name,passed:false,error:e.message});}};
 run(names[0],()=>{assert.equal(R.length,2);assert.deepEqual(R.map(r=>({entryId:r.entryId,path:r.path})),[{entryId:'ai-模型与评测-7',path:['items',0,'a']},{entryId:'ai-模型与评测-7',path:['items',0,'lead']}]);for(const r of R){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);assert.equal(leaf(r),r.after,'UNAPPLIED_OR_CHANGED '+r.path.join('/'));}});
 run(names[1],()=>{assert.equal(A.additions.length,1);const a=A.additions[0],e=get(a.entryId);assert.equal(a.entryId,'own-theory-architectures');assert.equal(a.questionId,'q-own-theory-sequence-scaling');assert.equal(a.expectedIndex,3);assert.equal(a.expectedOldCount,3);assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);assert.equal(sha(a.expectedItem.a),a.afterSha256);assert.deepEqual(A.completeBeforeEntry,B.appendEntry);assert.deepEqual(A.completeAfterAppendEntry.items.slice(0,3),B.appendEntry.items);assert.deepEqual(e.items.slice(0,3),B.appendEntry.items,'old prefix drift');assert.deepEqual(e,A.completeAfterAppendEntry,'new item or unowned entry fields changed');});
 run(names[2],()=>{const e=get(B.sourceEntryId),expected=structuredClone(B.sourceItem);for(const r of R)expected[r.path.at(-1)]=r.after;assert.deepEqual(e.items[0],expected,'owned source item changed outside a/lead or not applied');assert.deepEqual(Object.fromEntries(Object.entries(e).filter(([k])=>k!=='items')),B.sourceEntryFields);assert.equal(e.items.length,B.sourceItemIdentities.length);for(const it of B.sourceItemIdentities){const x=e.items[it.index];assert.equal('id'in x,it.idPresent);assert.equal(x.id??null,it.id??null);assert.equal(x.q,it.q);}});
 run(names[3],()=>{assert.equal(M.sourceBlockCount,31);assert.equal(M.maps.length,31);for(const field of ['a','lead']){const r=R.find(x=>x.path.at(-1)===field),blocks=[...r.before.matchAll(blockRx)],maps=M.maps.filter(x=>x.sourceField===field);assert.equal(blocks.length,field==='a'?29:2);assert.equal(maps.length,blocks.length);for(const[i,m]of maps.entries()){assert.equal(m.sourceKey,'ai-模型与评测-7#0');assert.equal(m.sourceBlockIndex,i);assert.equal(m.sourceHtml,blocks[i][0]);assert.equal(sha(m.sourceHtml),m.sourceSha256);assert.equal(Array.from(r.before).slice(...m.sourceSpanCodePoints).join(''),m.sourceHtml);assert.ok(m.destinations.length);for(const d of m.destinations){assert.equal(sha(d.html),d.sha256);const witness=S[d.sectionName];assert.ok(witness,'unknown section');assert.equal(d.html,witness.html);assert.equal(d.stableReviewKey,witness.stableReviewKey);for(const f of d.fragments||[d.html]){assert.ok(/<p\b/.test(f),'heading/link-only destination');assert.ok(plain(f).length>35,'insubstantial destination');assert.ok(get(d.stableReviewKey).a.includes(f),d.stableReviewKey+' missing substantive witness for '+field+'#'+i);}}}}});
 run(names[4],()=>{assert.equal(V.originalCount,11);assert.equal(V.variants.length,11);assert.equal(new Set(V.variants.map(v=>v.text)).size,11);const a=get('ai-模型与评测-7#0').a,folds=[...a.matchAll(/<details\b[^>]*>[\s\S]*?<\/details>/g)].map(x=>x[0]);assert.equal(folds.length,1);assert.equal([...folds[0].matchAll(/<li\b/g)].length,6);assert.equal(V.variants.filter(v=>v.folded).length,6);for(const v of V.variants){assert.ok(B.sourceItem[v.sourceField].includes(v.sourceExact),'wording not in original');assert.ok(plain(get(v.retainedAt)[v.retainedField]).includes(v.text),'wording lost '+v.text);assert.ok(v.destinations.length);if(v.folded)assert.ok(plain(folds[0]).includes(v.text));for(const d of v.destinations)for(const f of d.fragments||[d.html])assert.ok(get(d.stableReviewKey).a.includes(f),'wording has no actual answer '+v.text);}});
 run(names[5],()=>{assert.equal(D.crossWorkerDependencies.length,0);assert.equal(D.dependencies.length,5);assert.equal(new Set(D.dependencies.map(d=>d.stableReviewKey)).size,4);for(const d of D.dependencies){assert.equal(sha(d.sourceBody),d.sourceBodySha256);assert.equal(get(d.stableReviewKey).a,d.sourceBody,'canonical body drift '+d.stableReviewKey);assert.equal(sha(d.html),d.sha256);for(const f of d.fragments){assert.ok(d.sourceBody.includes(f));assert.ok(get(d.stableReviewKey).a.includes(f));assert.ok(plain(f).length>35);}}});
 run(names[6],()=>{assert.equal(C.conditions.length,16);for(const c of C.conditions){assert.ok(c.statement.length>35,'condition must be a substantive statement');const s=S[c.sectionName];assert.ok(s,'missing condition section');assert.ok(plain(s.html).includes(c.statement),'unreviewed condition');assert.ok(plain(get(s.stableReviewKey).a).includes(c.statement),c.id+' substantive boundary lost');assert.ok(c.reason&&c.sourceBlocks.length);}});
 run(names[7],()=>{const cases=[{routedCorrectly:true,expertCorrect:true},{routedCorrectly:true,expertCorrect:true},{routedCorrectly:false,expertCorrect:false},{routedCorrectly:false,expertCorrect:false}],n=cases.length,correctRoute=cases.filter(x=>x.routedCorrectly),wrongRoute=cases.filter(x=>!x.routedCorrectly);const cond=correctRoute.filter(x=>x.expertCorrect).length/correctRoute.length,end=cases.filter(x=>x.expertCorrect).length/n,weighted=correctRoute.length/n*cond+wrongRoute.length/n*(wrongRoute.filter(x=>x.expertCorrect).length/wrongRoute.length);assert.equal(end,weighted);const unifiedCorrect=[true,true,true,false].filter(Boolean).length/n;assert.ok(cond>unifiedCorrect&&end<unifiedCorrect);assert.notEqual(end,cond);const required=S['classifier-evaluation'];assert.ok(get(required.stableReviewKey).a.includes(required.html),'actual route and denominator explanation absent');});
 run(names[8],()=>{const bodies=R.map(leaf).concat(A.additions.map(a=>get(a.entryId+'#'+a.questionId).a));for(const r of R)for(const m of r.before.matchAll(/\bid="[^"]+"/g))assert.ok(leaf(r).includes(m[0]),'old anchor removed');for(const a of bodies){balanced(a);assert.ok(!/<(?:script|iframe|form|input|button)\b|\son\w+\s*=|javascript:/i.test(a),'active HTML');for(const m of a.matchAll(/href="#\/e\/([^"#]+)"/g)){const[e,q]=m[1].split('/').map(decodeURIComponent);get(e+(q===undefined?'':'#'+q));}}});
 run(names[9],()=>{const a=R.map(leaf).concat(A.additions.map(a=>get(a.entryId+'#'+a.questionId).a)).join('');assert.ok(!/<(?:pre|code)\b/.test(a));assert.ok(!/preservation-map|beforeSha256|authoring compiler|原题变体索引|已完成GPU实验|实测提升了|我们已经达到/.test(a));assert.ok(a.includes('没有模型实验结果'));});
 return{passed:checks.every(c=>c.passed),checks,mode:'actual-dist-only',dist:path.resolve(dist),overlay:false,siteWrites:0,limitations:['Read-only actual dist validation; no GPU, model training, serving benchmark or browser test.','Counterexample is a mathematical fixture, not project data.','Final acceptance requires the parent to integrate and build the real site; no candidate overlay or fallback is accepted.']};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const args=process.argv.slice(2);try{assert.equal(args.length,2,'only --dist ABSOLUTE_PATH allowed');assert.equal(args[0],'--dist');assert.ok(path.isAbsolute(args[1]));const report=verify(args[1]);console.log(JSON.stringify(report,null,2));if(!report.passed)process.exitCode=1;}catch(e){console.error(e.stack);process.exitCode=1;}}
